package com.example.studentintelligentsystem;

import android.content.Intent;
import android.os.Bundle;
import android.view.Menu;
import android.view.MenuItem;
import androidx.appcompat.app.AppCompatActivity;
import androidx.appcompat.widget.Toolbar;
import androidx.cardview.widget.CardView;

public class AdminDashboardActivity extends AppCompatActivity {

    private CardView cardRegisterTeacher, cardRegisterParent, cardPostAnnouncement, cardManageAnnouncements, cardViewTeachers;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_admin_dashboard);

        Toolbar toolbar = findViewById(R.id.toolbar);
        setSupportActionBar(toolbar);

        cardRegisterTeacher = findViewById(R.id.cardRegisterTeacher);
        cardRegisterParent = findViewById(R.id.cardRegisterParent);
        cardPostAnnouncement = findViewById(R.id.cardPostAnnouncement);
        cardManageAnnouncements = findViewById(R.id.cardManageAnnouncements);
        cardViewTeachers = findViewById(R.id.cardViewTeachers);

        cardRegisterTeacher.setOnClickListener(v -> {
            Intent intent = new Intent(this, TeacherRegisterActivity.class);
            startActivity(intent);
        });

        cardRegisterParent.setOnClickListener(v -> {
            Intent intent = new Intent(this, ParentRegisterActivity.class);
            startActivity(intent);
        });

        cardPostAnnouncement.setOnClickListener(v -> {
            Intent intent = new Intent(this, PostAnnouncementActivity.class);
            startActivity(intent);
        });

        cardManageAnnouncements.setOnClickListener(v -> {
            Intent intent = new Intent(this, ManageAnnouncementsActivity.class);
            startActivity(intent);
        });

        cardViewTeachers.setOnClickListener(v -> {
            Intent intent = new Intent(this, ViewTeachersActivity.class);
            startActivity(intent);
        });
    }

    @Override
    public boolean onCreateOptionsMenu(Menu menu) {
        getMenuInflater().inflate(R.menu.menu_logout, menu);
        return true;
    }

    @Override
    public boolean onOptionsItemSelected(MenuItem item) {
        if (item.getItemId() == R.id.action_logout) {
            logout();
            return true;
        }
        return super.onOptionsItemSelected(item);
    }

    @Override
    public void onBackPressed() {
        // Overriding to do nothing and stay on the dashboard
    }

    private void logout() {
        Intent intent = new Intent(this, LoginActivity.class);
        intent.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TASK);
        startActivity(intent);
        finish();
    }
}

package com.example.studentintelligentsystem;

import android.content.Intent;
import android.os.Bundle;
import android.util.Log;
import android.view.Menu;
import android.view.MenuItem;
import android.widget.Toast;
import androidx.appcompat.app.AppCompatActivity;
import androidx.appcompat.widget.Toolbar;
import androidx.cardview.widget.CardView;

public class AdminDashboardActivity extends AppCompatActivity {
    private static final String TAG = "AdminDashboardActivity";

    private CardView cardRegisterTeacher, cardRegisterParent, cardPostAnnouncement, 
                     cardManageAnnouncements, cardViewTeachers;
    private AnnouncementLoader announcementLoader;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_admin_dashboard);

        Toolbar toolbar = findViewById(R.id.toolbar);
        setSupportActionBar(toolbar);

        announcementLoader = new AnnouncementLoader(this);

        cardRegisterTeacher = findViewById(R.id.cardRegisterTeacher);
        cardRegisterParent = findViewById(R.id.cardRegisterParent);
        cardPostAnnouncement = findViewById(R.id.cardPostAnnouncement);
        cardManageAnnouncements = findViewById(R.id.cardManageAnnouncements);
        cardViewTeachers = findViewById(R.id.cardViewTeachers);

        cardRegisterTeacher.setOnClickListener(v -> {
            Intent intent = new Intent(this, TeacherRegisterActivity.class);
            startActivity(intent);
        });

        cardRegisterParent.setOnClickListener(v -> {
            Intent intent = new Intent(this, ParentRegisterActivity.class);
            startActivity(intent);
        });

        cardPostAnnouncement.setOnClickListener(v -> {
            Intent intent = new Intent(this, PostAnnouncementActivity.class);
            startActivity(intent);
        });

        cardManageAnnouncements.setOnClickListener(v -> {
            Intent intent = new Intent(this, ManageAnnouncementsActivity.class);
            startActivity(intent);
        });

        cardViewTeachers.setOnClickListener(v -> {
            Intent intent = new Intent(this, ViewTeachersActivity.class);
            startActivity(intent);
        });

        // Load initial data
        syncDataFromSupabase();
    }

    @Override
    protected void onResume() {
        super.onResume();
        // Refresh data when returning to dashboard
        syncDataFromSupabase();
    }

    @Override
    public boolean onCreateOptionsMenu(Menu menu) {
        getMenuInflater().inflate(R.menu.menu_admin_dashboard, menu);
        return true;
    }

    @Override
    public boolean onOptionsItemSelected(MenuItem item) {
        int id = item.getItemId();

        if (id == R.id.action_refresh) {
            syncDataFromSupabase();
            return true;
        } else if (id == R.id.action_logout) {
            logout();
            return true;
        }

        return super.onOptionsItemSelected(item);
    }

    @Override
    public void onBackPressed() {
        // Overriding to do nothing and stay on the dashboard
    }

    private void syncDataFromSupabase() {
        Toast.makeText(this, "Syncing data from cloud...", Toast.LENGTH_SHORT).show();

        // Sync announcements
        announcementLoader.syncAnnouncementsFromSupabase((success, message) -> {
            runOnUiThread(() -> {
                if (success) {
                    Log.d(TAG, "✓ " + message);
                    Toast.makeText(this, "Data synced successfully", Toast.LENGTH_SHORT).show();
                } else {
                    Log.e(TAG, "✗ Sync failed: " + message);
                    Toast.makeText(this, "Sync completed with errors", Toast.LENGTH_SHORT).show();
                }
            });
        });
    }

    private void logout() {
        Intent intent = new Intent(this, LoginActivity.class);
        intent.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TASK);
        startActivity(intent);
        finish();
    }
}

package com.example.studentintelligentsystem;

import android.content.Context;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.util.Log;

import com.example.studentintelligentsystem.supabase.SupabaseClient;
import com.example.studentintelligentsystem.supabase.SupabaseConfig;

import org.json.JSONArray;
import org.json.JSONObject;

import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.List;
import java.util.Locale;

/**
 * Helper class to load announcements from both local database and Supabase
 * Provides unified announcement loading across all views
 */
public class AnnouncementLoader {
    private static final String TAG = "AnnouncementLoader";

    private Context context;
    private DatabaseHelper dbHelper;

    public AnnouncementLoader(Context context) {
        this.context = context;
        this.dbHelper = new DatabaseHelper(context);
    }

    /**
     * Load announcements for admin view (all announcements)
     */
    public List<String> loadAdminAnnouncements() {
        return loadAnnouncementsFromLocal(null, null);
    }

    /**
     * Load announcements for teacher view (grade-specific + general)
     */
    public List<String> loadTeacherAnnouncements(int teacherGrade) {
        String selection = DatabaseHelper.ANNOUNCEMENT_GRADE_TARGET + " = ? OR " + 
                          DatabaseHelper.ANNOUNCEMENT_GRADE_TARGET + " IS NULL";
        String[] selectionArgs = {String.valueOf(teacherGrade)};
        return loadAnnouncementsFromLocal(selection, selectionArgs);
    }

    /**
     * Load announcements for parent view (children's grades + general)
     */
    public List<String> loadParentAnnouncements(List<Integer> childrenGrades) {
        if (childrenGrades == null || childrenGrades.isEmpty()) {
            // Load only general announcements
            String selection = DatabaseHelper.ANNOUNCEMENT_GRADE_TARGET + " IS NULL";
            return loadAnnouncementsFromLocal(selection, null);
        }

        // Build selection for multiple grades
        StringBuilder selection = new StringBuilder();
        selection.append("(");
        List<String> selectionArgs = new ArrayList<>();

        for (int i = 0; i < childrenGrades.size(); i++) {
            if (i > 0) selection.append(" OR ");
            selection.append(DatabaseHelper.ANNOUNCEMENT_GRADE_TARGET).append(" = ?");
            selectionArgs.add(String.valueOf(childrenGrades.get(i)));
        }

        selection.append(" OR ").append(DatabaseHelper.ANNOUNCEMENT_GRADE_TARGET).append(" IS NULL)");

        return loadAnnouncementsFromLocal(selection.toString(), 
                selectionArgs.toArray(new String[0]));
    }

    /**
     * Load announcements from local database with optional filtering
     */
    private List<String> loadAnnouncementsFromLocal(String selection, String[] selectionArgs) {
        List<String> announcementList = new ArrayList<>();
        SQLiteDatabase db = dbHelper.getReadableDatabase();

        Cursor cursor = db.query(
                DatabaseHelper.TABLE_ANNOUNCEMENT,
                new String[]{
                    DatabaseHelper.ANNOUNCEMENT_TITLE,
                    DatabaseHelper.ANNOUNCEMENT_MESSAGE,
                    DatabaseHelper.ANNOUNCEMENT_SOURCE_LABEL,
                    DatabaseHelper.ANNOUNCEMENT_TIMESTAMP,
                    DatabaseHelper.ANNOUNCEMENT_GRADE_TARGET
                },
                selection,
                selectionArgs,
                null, null,
                DatabaseHelper.ANNOUNCEMENT_TIMESTAMP + " DESC"
        );

        if (cursor != null && cursor.moveToFirst()) {
            do {
                String title = cursor.getString(cursor.getColumnIndexOrThrow(
                        DatabaseHelper.ANNOUNCEMENT_TITLE));
                String message = cursor.getString(cursor.getColumnIndexOrThrow(
                        DatabaseHelper.ANNOUNCEMENT_MESSAGE));
                String source = cursor.getString(cursor.getColumnIndexOrThrow(
                        DatabaseHelper.ANNOUNCEMENT_SOURCE_LABEL));
                String timestamp = cursor.getString(cursor.getColumnIndexOrThrow(
                        DatabaseHelper.ANNOUNCEMENT_TIMESTAMP));

                // Format timestamp
                String formattedTimestamp = formatTimestamp(timestamp);

                // Get grade target if exists
                int gradeColumnIndex = cursor.getColumnIndexOrThrow(
                        DatabaseHelper.ANNOUNCEMENT_GRADE_TARGET);
                String gradeInfo = cursor.isNull(gradeColumnIndex) ? 
                        "All Grades" : "Grade " + cursor.getInt(gradeColumnIndex);

                announcementList.add(
                    "[" + source + "] " + title + "\n" + 
                    message + "\n" + 
                    gradeInfo + " • " + formattedTimestamp
                );
            } while (cursor.moveToNext());
            cursor.close();
        }
        db.close();

        if (announcementList.isEmpty()) {
            announcementList.add("No announcements available.\nPull down to refresh from cloud.");
        }

        return announcementList;
    }

    /**
     * Sync announcements from Supabase to local database
     */
    public void syncAnnouncementsFromSupabase(OnSyncCompleteListener listener) {
        if (!SupabaseConfig.isConfigured()) {
            if (listener != null) {
                listener.onSyncComplete(false, "Supabase not configured");
            }
            return;
        }

        new Thread(() -> {
            try {
                SupabaseClient client = SupabaseClient.getInstance();
                String response = client.queryData("announcements", 
                        "select=*&order=timestamp.desc");

                if (response != null) {
                    JSONArray announcements = new JSONArray(response);
                    Log.d(TAG, "✓ Loaded " + announcements.length() + 
                            " announcements from Supabase");

                    // Sync to local database
                    syncAnnouncementsToLocal(announcements);

                    if (listener != null) {
                        listener.onSyncComplete(true, 
                                "Synced " + announcements.length() + " announcements");
                    }
                } else {
                    if (listener != null) {
                        listener.onSyncComplete(false, "No data from Supabase");
                    }
                }
            } catch (Exception e) {
                Log.e(TAG, "Error syncing announcements: " + e.getMessage());
                if (listener != null) {
                    listener.onSyncComplete(false, e.getMessage());
                }
            }
        }).start();
    }

    /**
     * Sync announcements array to local database
     */
    private void syncAnnouncementsToLocal(JSONArray announcements) {
        try {
            SQLiteDatabase db = dbHelper.getWritableDatabase();

            for (int i = 0; i < announcements.length(); i++) {
                JSONObject announcement = announcements.getJSONObject(i);

                android.content.ContentValues values = new android.content.ContentValues();
                values.put(DatabaseHelper.ANNOUNCEMENT_ID, announcement.getInt("id"));
                values.put(DatabaseHelper.ANNOUNCEMENT_TITLE, 
                        announcement.getString("title"));
                values.put(DatabaseHelper.ANNOUNCEMENT_MESSAGE, 
                        announcement.getString("message"));
                values.put(DatabaseHelper.ANNOUNCEMENT_ROLE, 
                        announcement.optString("created_by_role", "System"));
                values.put(DatabaseHelper.ANNOUNCEMENT_FK_CREATOR_ID, 
                        announcement.optInt("created_by_id", 0));

                if (!announcement.isNull("grade_target")) {
                    values.put(DatabaseHelper.ANNOUNCEMENT_GRADE_TARGET, 
                            announcement.getInt("grade_target"));
                }

                values.put(DatabaseHelper.ANNOUNCEMENT_SOURCE_LABEL, 
                        announcement.optString("source_label", "System"));
                values.put(DatabaseHelper.ANNOUNCEMENT_TIMESTAMP, 
                        announcement.getString("timestamp"));

                db.insertWithOnConflict(DatabaseHelper.TABLE_ANNOUNCEMENT, null, values,
                        SQLiteDatabase.CONFLICT_REPLACE);
            }

            db.close();
            Log.d(TAG, "✓ Synced " + announcements.length() + " announcements to local");
        } catch (Exception e) {
            Log.e(TAG, "Error syncing announcements to local: " + e.getMessage());
        }
    }

    /**
     * Format timestamp for display
     */
    private String formatTimestamp(String timestamp) {
        SimpleDateFormat inputFormat = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss", 
                Locale.getDefault());
        SimpleDateFormat outputFormat = new SimpleDateFormat("MMM dd, yyyy - hh:mm a", 
                Locale.getDefault());

        try {
            Date date = inputFormat.parse(timestamp);
            return outputFormat.format(date);
        } catch (Exception e) {
            return timestamp; // Return raw timestamp if parsing fails
        }
    }

    /**
     * Interface for sync completion callback
     */
    public interface OnSyncCompleteListener {
        void onSyncComplete(boolean success, String message);
    }
}

package com.example.studentintelligentsystem;

import android.content.Context;
import android.content.Intent;
import android.content.SharedPreferences;
import android.database.Cursor;
import android.os.Bundle;
import android.text.TextUtils;
import android.view.View;
import android.widget.ArrayAdapter;
import android.widget.Button;
import android.widget.EditText;
import android.widget.Spinner;
import android.widget.TextView;
import android.widget.Toast;

import androidx.appcompat.app.AppCompatActivity;

public class LoginActivity extends AppCompatActivity {

    private Spinner spinnerRole;
    private EditText editLoginEmail, editLoginPassword;
    private Button btnLogin;
    private TextView tvRegisterPrompt;
    private DatabaseHelper dbHelper;

    // SharedPreferences constants
    public static final String PREFS_NAME = "StudentIntelligentSystemPrefs";
    public static final String KEY_USER_ID = "loggedInUserId";
    public static final String KEY_USER_ROLE = "loggedInUserRole";
    public static final String KEY_USER_GRADE = "loggedInUserGrade"; // For Teachers

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_login);

        dbHelper = new DatabaseHelper(this);

        spinnerRole = findViewById(R.id.spinnerRole);
        editLoginEmail = findViewById(R.id.editLoginEmail);
        editLoginPassword = findViewById(R.id.editLoginPassword);
        btnLogin = findViewById(R.id.btnLogin);
        tvRegisterPrompt = findViewById(R.id.tvRegisterPrompt);

        // Populate the role spinner
        ArrayAdapter<CharSequence> adapter = ArrayAdapter.createFromResource(this,
                R.array.roles_array, android.R.layout.simple_spinner_item);
        adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
        spinnerRole.setAdapter(adapter);

        // Set listeners
        btnLogin.setOnClickListener(v -> handleLogin());
        tvRegisterPrompt.setOnClickListener(v -> {
            Intent intent = new Intent(LoginActivity.this, AdminRegisterActivity.class);
            startActivity(intent);
        });
    }

    private void handleLogin() {
        String role = spinnerRole.getSelectedItem().toString();
        String email = editLoginEmail.getText().toString().trim();
        String password = editLoginPassword.getText().toString().trim();

        if (TextUtils.isEmpty(email) || TextUtils.isEmpty(password)) {
            Toast.makeText(this, "Email and password are required.", Toast.LENGTH_SHORT).show();
            return;
        }

        Cursor loggedInUser = dbHelper.checkLogin(email, password, role);

        if (loggedInUser != null && loggedInUser.moveToFirst()) {
            int userId = -1;
            int userGrade = -1; // Specific to teachers

            // --- Store Session --- 
            SharedPreferences.Editor editor = getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE).edit();

            if (role.equals("Admin")) {
                userId = loggedInUser.getInt(loggedInUser.getColumnIndexOrThrow(DatabaseHelper.ADMIN_ID));
            } else if (role.equals("Teacher")) {
                userId = loggedInUser.getInt(loggedInUser.getColumnIndexOrThrow(DatabaseHelper.TEACHER_ID));
                userGrade = loggedInUser.getInt(loggedInUser.getColumnIndexOrThrow(DatabaseHelper.TEACHER_GRADE_ASSIGNED));
            } else if (role.equals("Parent")) {
                userId = loggedInUser.getInt(loggedInUser.getColumnIndexOrThrow(DatabaseHelper.PARENT_ID));
            }

            editor.putInt(KEY_USER_ID, userId);
            editor.putString(KEY_USER_ROLE, role);
            if (userGrade != -1) {
                editor.putInt(KEY_USER_GRADE, userGrade);
            }
            editor.apply();

            loggedInUser.close();

            Toast.makeText(this, "Login Successful! Welcome " + role, Toast.LENGTH_SHORT).show();

            // --- Redirect to respective dashboard ---
            Intent intent;
            if (role.equals("Admin")) {
                intent = new Intent(this, AdminDashboardActivity.class);
            } else if (role.equals("Teacher")) {
                 intent = new Intent(this, TeacherDashboardActivity.class);
            } else {
                 intent = new Intent(this, ParentDashboardActivity.class);
            }
            startActivity(intent);
            finish(); // Prevents user from going back to login screen

        } else {
            Toast.makeText(this, "Login Failed. Invalid credentials or role.", Toast.LENGTH_LONG).show();
        }
    }
}

package com.example.studentintelligentsystem;

import android.content.Context;
import android.content.Intent;
import android.content.SharedPreferences;
import android.database.Cursor;
import android.os.Bundle;
import android.text.TextUtils;
import android.util.Log;
import android.view.View;
import android.widget.ArrayAdapter;
import android.widget.Button;
import android.widget.EditText;
import android.widget.Spinner;
import android.widget.TextView;
import android.widget.Toast;

import androidx.appcompat.app.AppCompatActivity;

import com.example.studentintelligentsystem.supabase.SupabaseAuthManager;
import com.example.studentintelligentsystem.supabase.SupabaseConfig;

import org.json.JSONObject;

public class LoginActivity extends AppCompatActivity {

    private static final String TAG = "LoginActivity";
    private Spinner spinnerRole;
    private EditText editLoginEmail, editLoginPassword;
    private Button btnLogin;
    private TextView tvRegisterPrompt;
    private DatabaseHelper dbHelper;
    private SupabaseAuthManager supabaseAuth;

    // SharedPreferences constants
    public static final String PREFS_NAME = "StudentIntelligentSystemPrefs";
    public static final String KEY_USER_ID = "loggedInUserId";
    public static final String KEY_USER_ROLE = "loggedInUserRole";
    public static final String KEY_USER_GRADE = "loggedInUserGrade"; // For Teachers

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_login);

        dbHelper = new DatabaseHelper(this);
        supabaseAuth = new SupabaseAuthManager();

        spinnerRole = findViewById(R.id.spinnerRole);
        editLoginEmail = findViewById(R.id.editLoginEmail);
        editLoginPassword = findViewById(R.id.editLoginPassword);
        btnLogin = findViewById(R.id.btnLogin);
        tvRegisterPrompt = findViewById(R.id.tvRegisterPrompt);

        // Populate the role spinner
        ArrayAdapter<CharSequence> adapter = ArrayAdapter.createFromResource(this,
                R.array.roles_array, android.R.layout.simple_spinner_item);
        adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);
        spinnerRole.setAdapter(adapter);

        // Set listeners
        btnLogin.setOnClickListener(v -> handleLogin());
        tvRegisterPrompt.setOnClickListener(v -> {
            Intent intent = new Intent(LoginActivity.this, AdminRegisterActivity.class);
            startActivity(intent);
        });
    }

    private void handleLogin() {
        String role = spinnerRole.getSelectedItem().toString();
        String email = editLoginEmail.getText().toString().trim();
        String password = editLoginPassword.getText().toString().trim();

        if (TextUtils.isEmpty(email) || TextUtils.isEmpty(password)) {
            Toast.makeText(this, "Email and password are required.", Toast.LENGTH_SHORT).show();
            return;
        }

        // Show loading message
        Toast.makeText(this, "Authenticating...", Toast.LENGTH_SHORT).show();

        // Try Supabase authentication first (for multi-device login)
        new Thread(() -> {
            boolean loginSuccess = false;
            int userId = -1;
            int userGrade = -1;
            String userName = "";

            // STEP 1: Try Supabase Authentication
            if (SupabaseConfig.isConfigured()) {
                Log.i(TAG, "Attempting Supabase authentication for " + role);
                JSONObject userData = supabaseAuth.login(email, password, role);

                if (userData != null) {
                    try {
                        userId = userData.getInt("id");

                        if (role.equals("Teacher") && userData.has("grade_assigned")) {
                            userGrade = userData.getInt("grade_assigned");
                        }

                        if (userData.has("name")) {
                            userName = userData.getString("name");
                        } else if (userData.has("school_name")) {
                            userName = userData.getString("school_name");
                        }

                        loginSuccess = true;
                        Log.i(TAG, "✓ Supabase authentication successful");

                    } catch (Exception e) {
                        Log.e(TAG, "Error parsing Supabase response: " + e.getMessage());
                    }
                }
            }

            // STEP 2: Fallback to Local Authentication
            if (!loginSuccess) {
                Log.i(TAG, "Falling back to local authentication");
                Cursor loggedInUser = dbHelper.checkLogin(email, password, role);

                if (loggedInUser != null && loggedInUser.moveToFirst()) {
                    if (role.equals("Admin")) {
                        userId = loggedInUser.getInt(loggedInUser.getColumnIndexOrThrow(DatabaseHelper.ADMIN_ID));
                    } else if (role.equals("Teacher")) {
                        userId = loggedInUser.getInt(loggedInUser.getColumnIndexOrThrow(DatabaseHelper.TEACHER_ID));
                        userGrade = loggedInUser.getInt(loggedInUser.getColumnIndexOrThrow(DatabaseHelper.TEACHER_GRADE_ASSIGNED));
                    } else if (role.equals("Parent")) {
                        userId = loggedInUser.getInt(loggedInUser.getColumnIndexOrThrow(DatabaseHelper.PARENT_ID));
                    }

                    loginSuccess = true;
                    loggedInUser.close();
                    Log.i(TAG, "✓ Local authentication successful");
                }
            }

            // STEP 3: Handle Login Result
            final boolean finalLoginSuccess = loginSuccess;
            final int finalUserId = userId;
            final int finalUserGrade = userGrade;
            final String finalUserName = userName;

            runOnUiThread(() -> {
                if (finalLoginSuccess && finalUserId != -1) {
                    // Store session
                    SharedPreferences.Editor editor = getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE).edit();
                    editor.putInt(KEY_USER_ID, finalUserId);
                    editor.putString(KEY_USER_ROLE, role);
                    if (finalUserGrade != -1) {
                        editor.putInt(KEY_USER_GRADE, finalUserGrade);
                    }
                    editor.apply();

                    String welcomeMsg = "Login Successful! Welcome " + role;
                    if (!TextUtils.isEmpty(finalUserName)) {
                        welcomeMsg = "Welcome back, " + finalUserName + "!";
                    }
                    Toast.makeText(this, welcomeMsg, Toast.LENGTH_SHORT).show();

                    // Redirect to respective dashboard
                    Intent intent;
                    if (role.equals("Admin")) {
                        intent = new Intent(this, AdminDashboardActivity.class);
                    } else if (role.equals("Teacher")) {
                        intent = new Intent(this, TeacherDashboardActivity.class);
                    } else {
                        intent = new Intent(this, ParentDashboardActivity.class);
                    }
                    startActivity(intent);
                    finish();
                } else {
                    Toast.makeText(this, "Login Failed. Invalid credentials or role.", Toast.LENGTH_LONG).show();
                }
            });
        }).start();
    }
}

package com.example.studentintelligentsystem;

import android.content.Context;
import android.content.SharedPreferences;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.os.Bundle;
import android.text.TextUtils;
import android.widget.ArrayAdapter;
import android.widget.AutoCompleteTextView;
import android.widget.Button;
import android.widget.EditText;
import android.widget.RadioButton;
import android.widget.RadioGroup;
import android.widget.Toast;

import androidx.appcompat.app.AppCompatActivity;

import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.HashMap;
import java.util.Locale;

public class MarkAttendanceActivity extends AppCompatActivity {

    private AutoCompleteTextView spinnerStudents;
    private EditText editAttendanceDate;
    private RadioGroup rgAttendanceStatus;
    private Button btnSubmitAttendance;
    private DatabaseHelper dbHelper;

    private HashMap<String, Integer> studentMap = new HashMap<>();
    private int selectedStudentId = -1;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_mark_attendance);

        dbHelper = new DatabaseHelper(this);

        spinnerStudents = findViewById(R.id.spinnerStudents);
        editAttendanceDate = findViewById(R.id.editAttendanceDate);
        rgAttendanceStatus = findViewById(R.id.rgAttendanceStatus);
        btnSubmitAttendance = findViewById(R.id.btnSubmitAttendance);

        editAttendanceDate.setText(new SimpleDateFormat("yyyy-MM-dd", Locale.getDefault()).format(new Date()));

        loadStudentsForTeacher();

        spinnerStudents.setOnItemClickListener((parent, view, position, id) -> {
            String selectedName = (String) parent.getItemAtPosition(position);
            selectedStudentId = studentMap.get(selectedName);
        });

        btnSubmitAttendance.setOnClickListener(v -> markAttendance());
    }

    private void loadStudentsForTeacher() {
        SharedPreferences prefs = getSharedPreferences(LoginActivity.PREFS_NAME, Context.MODE_PRIVATE);
        int teacherGrade = prefs.getInt(LoginActivity.KEY_USER_GRADE, -1);

        if (teacherGrade == -1) return;

        SQLiteDatabase db = dbHelper.getReadableDatabase();
        Cursor cursor = db.query(DatabaseHelper.TABLE_STUDENT, new String[]{DatabaseHelper.STUDENT_ID, DatabaseHelper.STUDENT_NAME}, DatabaseHelper.STUDENT_GRADE + " = ?", new String[]{String.valueOf(teacherGrade)}, null, null, null);

        ArrayList<String> studentNames = new ArrayList<>();
        if (cursor != null && cursor.moveToFirst()) {
            do {
                int id = cursor.getInt(cursor.getColumnIndexOrThrow(DatabaseHelper.STUDENT_ID));
                String name = cursor.getString(cursor.getColumnIndexOrThrow(DatabaseHelper.STUDENT_NAME));
                studentMap.put(name, id);
                studentNames.add(name);
            } while (cursor.moveToNext());
            cursor.close();
        }
        db.close();

        ArrayAdapter<String> adapter = new ArrayAdapter<>(this, android.R.layout.simple_dropdown_item_1line, studentNames);
        spinnerStudents.setAdapter(adapter);
    }

    private void markAttendance() {
        String date = editAttendanceDate.getText().toString().trim();
        int selectedStatusId = rgAttendanceStatus.getCheckedRadioButtonId();

        if (selectedStudentId == -1 || TextUtils.isEmpty(date) || selectedStatusId == -1) {
            Toast.makeText(this, "Please select a student, date, and status.", Toast.LENGTH_SHORT).show();
            return;
        }

        RadioButton selectedRadioButton = findViewById(selectedStatusId);
        String status = selectedRadioButton.getText().toString();

        SharedPreferences prefs = getSharedPreferences(LoginActivity.PREFS_NAME, Context.MODE_PRIVATE);
        int teacherId = prefs.getInt(LoginActivity.KEY_USER_ID, -1);

        dbHelper.addAttendance(selectedStudentId, date, status.equals("Present"));

        Toast.makeText(this, "Attendance marked successfully!", Toast.LENGTH_SHORT).show();
        finish();
    }
}

