package com.example.studentintelligentsystem;

/**
 * Model class representing a student result record
 */
public class Result {
    private int resultId;
    private int studentId;
    private String studentName;
    private String subject;
    private String term;
    private int marks;
    private String comment;

    public Result() {}

    public Result(int resultId, int studentId, String studentName, String subject, String term, int marks, String comment) {
        this.resultId = resultId;
        this.studentId = studentId;
        this.studentName = studentName;
        this.subject = subject;
        this.term = term;
        this.marks = marks;
        this.comment = comment;
    }

    public int getResultId() {
        return resultId;
    }

    public void setResultId(int resultId) {
        this.resultId = resultId;
    }

    public int getStudentId() {
        return studentId;
    }

    public void setStudentId(int studentId) {
        this.studentId = studentId;
    }

    public String getStudentName() {
        return studentName;
    }

    public void setStudentName(String studentName) {
        this.studentName = studentName;
    }

    public String getSubject() {
        return subject;
    }

    public void setSubject(String subject) {
        this.subject = subject;
    }

    public String getTerm() {
        return term;
    }

    public void setTerm(String term) {
        this.term = term;
    }

    public int getMarks() {
        return marks;
    }

    public void setMarks(int marks) {
        this.marks = marks;
    }

    public String getComment() {
        return comment;
    }

    public void setComment(String comment) {
        this.comment = comment;
    }
}

package com.example.studentintelligentsystem;

import android.content.ContentValues;
import android.content.Context;
import android.content.SharedPreferences;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.os.Bundle;
import android.text.TextUtils;
import android.util.Log;
import android.widget.Button;
import android.widget.EditText;
import android.widget.Toast;

import androidx.appcompat.app.AppCompatActivity;

import com.example.studentintelligentsystem.supabase.SupabaseSyncManager;
import com.example.studentintelligentsystem.supabase.SupabaseConfig;

public class StudentRegisterActivity extends AppCompatActivity {
    private static final String TAG = "StudentRegisterActivity";

    private EditText editStudentName, editStudentAge, editStudentGender, editStudentAddress, editParentEmailToLink;
    private Button btnRegisterStudent;
    private DatabaseHelper dbHelper;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_student_register);

        dbHelper = new DatabaseHelper(this);

        editStudentName = findViewById(R.id.editStudentName);
        editStudentAge = findViewById(R.id.editStudentAge);
        editStudentGender = findViewById(R.id.editStudentGender);
        editStudentAddress = findViewById(R.id.editStudentAddress);
        editParentEmailToLink = findViewById(R.id.editParentEmailToLink);
        btnRegisterStudent = findViewById(R.id.btnRegisterStudent);

        btnRegisterStudent.setOnClickListener(v -> registerStudent());
    }

    private void registerStudent() {
        String studentName = editStudentName.getText().toString().trim();
        String ageStr = editStudentAge.getText().toString().trim();
        String gender = editStudentGender.getText().toString().trim();
        String address = editStudentAddress.getText().toString().trim();
        String parentEmail = editParentEmailToLink.getText().toString().trim();

        if (TextUtils.isEmpty(studentName) || TextUtils.isEmpty(ageStr) || TextUtils.isEmpty(parentEmail)) {
            Toast.makeText(this, "Student Name, Age, and Parent Email are required.", Toast.LENGTH_SHORT).show();
            return;
        }

        // --- Get Teacher and Parent IDs ---
        SharedPreferences prefs = getSharedPreferences(LoginActivity.PREFS_NAME, Context.MODE_PRIVATE);
        int teacherId = prefs.getInt(LoginActivity.KEY_USER_ID, -1);
        int teacherGrade = prefs.getInt(LoginActivity.KEY_USER_GRADE, -1);
        long parentId = getParentIdByEmail(parentEmail);

        if (teacherId == -1 || teacherGrade == -1) {
            Toast.makeText(this, "Error: Could not verify logged-in teacher. Please log in again.", Toast.LENGTH_LONG).show();
            return;
        }

        if (parentId == -1) {
            Toast.makeText(this, "Error: No parent found with that email address. Please register the parent first.", Toast.LENGTH_LONG).show();
            return;
        }

        // --- Insert Student into Database ---
        SQLiteDatabase db = dbHelper.getWritableDatabase();
        ContentValues values = new ContentValues();
        values.put(DatabaseHelper.STUDENT_NAME, studentName);
        values.put(DatabaseHelper.STUDENT_AGE, Integer.parseInt(ageStr));
        values.put(DatabaseHelper.STUDENT_GENDER, gender);
        values.put(DatabaseHelper.STUDENT_ADDRESS, address);
        values.put(DatabaseHelper.STUDENT_GRADE, teacherGrade); // Automatically assign teacher's grade
        values.put(DatabaseHelper.STUDENT_FK_TEACHER_ID, teacherId); // Automatically link to this teacher
        values.put(DatabaseHelper.STUDENT_FK_PARENT_ID, parentId); // Link to the found parent

        long newRowId = db.insert(DatabaseHelper.TABLE_STUDENT, null, values);
        db.close();

        if (newRowId != -1) {
            Log.i(TAG, "✓ Student registered with ID: " + newRowId);
            Toast.makeText(this, "Student registered and linked successfully!", Toast.LENGTH_SHORT).show();

            // Sync to Supabase if configured
            if (SupabaseConfig.isConfigured()) {
                try {
                    SupabaseSyncManager syncManager = SupabaseSyncManager.getInstance(this);
                    Log.d(TAG, "Syncing student " + newRowId + " to Supabase...");
                    syncManager.syncStudent((int) newRowId);
                    Log.i(TAG, "✓ Student sync initiated to Supabase");
                } catch (Exception e) {
                    Log.e(TAG, "Failed to sync student to Supabase: " + e.getMessage());
                }
            }

            finish(); // Go back to the teacher dashboard
        } else {
            Toast.makeText(this, "Error registering student.", Toast.LENGTH_LONG).show();
        }
    }

    private long getParentIdByEmail(String email) {
        SQLiteDatabase db = dbHelper.getReadableDatabase();
        Cursor cursor = db.query(
                DatabaseHelper.TABLE_PARENT,
                new String[]{DatabaseHelper.PARENT_ID},
                DatabaseHelper.PARENT_EMAIL + " = ?",
                new String[]{email},
                null, null, null
        );

        if (cursor != null && cursor.moveToFirst()) {
            long parentId = cursor.getLong(cursor.getColumnIndexOrThrow(DatabaseHelper.PARENT_ID));
            cursor.close();
            db.close();
            return parentId;
        } else {
            if (cursor != null) cursor.close();
            db.close();
            return -1; // Parent not found
        }
    }
}

package com.example.studentintelligentsystem;

import android.content.ContentValues;
import android.content.Context;
import android.content.SharedPreferences;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.os.Bundle;
import android.text.TextUtils;
import android.util.Log;
import android.widget.Button;
import android.widget.EditText;
import android.widget.Toast;

import androidx.appcompat.app.AppCompatActivity;

import com.example.studentintelligentsystem.supabase.SupabaseSyncManager;
import com.example.studentintelligentsystem.supabase.SupabaseConfig;

public class StudentRegisterActivity extends AppCompatActivity {
    private static final String TAG = "StudentRegisterActivity";

    private EditText editStudentName, editStudentAge, editStudentGender, editStudentAddress, editParentEmailToLink;
    private Button btnRegisterStudent;
    private DatabaseHelper dbHelper;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_student_register);

        dbHelper = new DatabaseHelper(this);

        editStudentName = findViewById(R.id.editStudentName);
        editStudentAge = findViewById(R.id.editStudentAge);
        editStudentGender = findViewById(R.id.editStudentGender);
        editStudentAddress = findViewById(R.id.editStudentAddress);
        editParentEmailToLink = findViewById(R.id.editParentEmailToLink);
        btnRegisterStudent = findViewById(R.id.btnRegisterStudent);

        btnRegisterStudent.setOnClickListener(v -> registerStudent());
    }

    private void registerStudent() {
        String studentName = editStudentName.getText().toString().trim();
        String ageStr = editStudentAge.getText().toString().trim();
        String gender = editStudentGender.getText().toString().trim();
        String address = editStudentAddress.getText().toString().trim();
        String parentEmail = editParentEmailToLink.getText().toString().trim();

        if (TextUtils.isEmpty(studentName) || TextUtils.isEmpty(ageStr) || TextUtils.isEmpty(parentEmail)) {
            Toast.makeText(this, "Student Name, Age, and Parent Email are required.", Toast.LENGTH_SHORT).show();
            return;
        }

        // --- Get Teacher and Parent IDs ---
        SharedPreferences prefs = getSharedPreferences(LoginActivity.PREFS_NAME, Context.MODE_PRIVATE);
        int teacherId = prefs.getInt(LoginActivity.KEY_USER_ID, -1);
        int teacherGrade = prefs.getInt(LoginActivity.KEY_USER_GRADE, -1);
        long parentId = getParentIdByEmail(parentEmail);

        if (teacherId == -1 || teacherGrade == -1) {
            Toast.makeText(this, "Error: Could not verify logged-in teacher. Please log in again.", Toast.LENGTH_LONG).show();
            return;
        }

        if (parentId == -1) {
            Toast.makeText(this, "Error: No parent found with that email address. Please register the parent first.", Toast.LENGTH_LONG).show();
            return;
        }

        // --- Insert Student into Database ---
        SQLiteDatabase db = dbHelper.getWritableDatabase();
        ContentValues values = new ContentValues();
        values.put(DatabaseHelper.STUDENT_NAME, studentName);
        values.put(DatabaseHelper.STUDENT_AGE, Integer.parseInt(ageStr));
        values.put(DatabaseHelper.STUDENT_GENDER, gender);
        values.put(DatabaseHelper.STUDENT_ADDRESS, address);
        values.put(DatabaseHelper.STUDENT_GRADE, teacherGrade); // Automatically assign teacher's grade
        values.put(DatabaseHelper.STUDENT_FK_TEACHER_ID, teacherId); // Automatically link to this teacher
        values.put(DatabaseHelper.STUDENT_FK_PARENT_ID, parentId); // Link to the found parent

        long newRowId = db.insert(DatabaseHelper.TABLE_STUDENT, null, values);
        db.close();

        if (newRowId != -1) {
            Log.i(TAG, "✓ Student registered with ID: " + newRowId);
            Toast.makeText(this, "Student registered and linked successfully!", Toast.LENGTH_SHORT).show();

            // Sync to Supabase if configured
            if (SupabaseConfig.isConfigured()) {
                try {
                    SupabaseSyncManager syncManager = SupabaseSyncManager.getInstance(this);
                    Log.d(TAG, "Syncing student " + newRowId + " to Supabase...");
                    syncManager.syncStudent((int) newRowId);
                    Log.i(TAG, "✓ Student sync initiated to Supabase");
                } catch (Exception e) {
                    Log.e(TAG, "Failed to sync student to Supabase: " + e.getMessage());
                }
            }

            finish(); // Go back to the teacher dashboard
        } else {
            Toast.makeText(this, "Error registering student.", Toast.LENGTH_LONG).show();
        }
    }

    private long getParentIdByEmail(String email) {
        // First check local database
        SQLiteDatabase db = dbHelper.getReadableDatabase();
        Cursor cursor = db.query(
                DatabaseHelper.TABLE_PARENT,
                new String[]{DatabaseHelper.PARENT_ID},
                DatabaseHelper.PARENT_EMAIL + " = ?",
                new String[]{email},
                null, null, null
        );

        if (cursor != null && cursor.moveToFirst()) {
            long parentId = cursor.getLong(cursor.getColumnIndexOrThrow(DatabaseHelper.PARENT_ID));
            cursor.close();
            db.close();
            Log.d(TAG, "✓ Parent found locally with email: " + email);
            return parentId;
        }

        if (cursor != null) cursor.close();
        db.close();

        // If not found locally and Supabase is configured, check Supabase
        if (SupabaseConfig.isConfigured()) {
            try {
                Log.d(TAG, "Checking Supabase for parent with email: " + email);

                // Query Supabase in background thread
                final long[] result = {-1};
                Thread thread = new Thread(() -> {
                    try {
                        com.example.studentintelligentsystem.supabase.SupabaseClient client = 
                            com.example.studentintelligentsystem.supabase.SupabaseClient.getInstance();

                        org.json.JSONObject parentData = client.getParentByEmail(email);

                        if (parentData != null) {
                            // Parent exists in Supabase, sync to local database
                            Log.d(TAG, "✓ Parent found in Supabase, syncing to local database");
                            long parentId = dbHelper.insertOrUpdateParentFromSupabase(parentData);
                            result[0] = parentId;
                        } else {
                            Log.d(TAG, "Parent not found in Supabase either");
                            result[0] = -1;
                        }
                    } catch (Exception e) {
                        Log.e(TAG, "Error checking Supabase for parent: " + e.getMessage());
                        result[0] = -1;
                    }
                });

                thread.start();
                thread.join(5000); // Wait up to 5 seconds

                return result[0];

            } catch (Exception e) {
                Log.e(TAG, "Error querying parent from Supabase: " + e.getMessage());
                return -1;
            }
        }

        // Parent not found locally or in Supabase
        Log.d(TAG, "Parent not found with email: " + email);
        return -1;
    }
}

package com.example.studentintelligentsystem;

import android.content.Context;
import android.content.Intent;
import android.content.SharedPreferences;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.os.Bundle;
import android.view.Menu;
import android.view.MenuItem;
import android.widget.ArrayAdapter;
import android.widget.ListView;
import android.widget.TextView;
import androidx.appcompat.app.AppCompatActivity;
import androidx.appcompat.widget.Toolbar;
import androidx.cardview.widget.CardView;

import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.Locale;

public class TeacherDashboardActivity extends AppCompatActivity {

    private TextView tvTeacherWelcome;
    private CardView cardRegisterStudent, cardMarkAttendance, cardAddResults, cardManageSubjects, cardPostTeacherAnnouncement, cardManageAnnouncements, cardViewParents;
    private ListView lvTeacherAnnouncements;
    private DatabaseHelper dbHelper;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_teacher_dashboard);

        Toolbar toolbar = findViewById(R.id.toolbar);
        setSupportActionBar(toolbar);

        dbHelper = new DatabaseHelper(this);
        tvTeacherWelcome = findViewById(R.id.tvTeacherWelcome);
        cardRegisterStudent = findViewById(R.id.cardRegisterStudent);
        cardMarkAttendance = findViewById(R.id.cardMarkAttendance);
        cardAddResults = findViewById(R.id.cardAddResults);
        cardManageSubjects = findViewById(R.id.cardManageSubjects);
        cardPostTeacherAnnouncement = findViewById(R.id.cardPostTeacherAnnouncement);
        cardManageAnnouncements = findViewById(R.id.cardManageAnnouncements);
        cardViewParents = findViewById(R.id.cardViewParents);
        lvTeacherAnnouncements = findViewById(R.id.lvTeacherAnnouncements);

        SharedPreferences prefs = getSharedPreferences(LoginActivity.PREFS_NAME, Context.MODE_PRIVATE);
        int teacherGrade = prefs.getInt(LoginActivity.KEY_USER_GRADE, -1);

        if (teacherGrade != -1) {
            tvTeacherWelcome.setText("Teacher Dashboard (Grade " + teacherGrade + ")");
        } else {
            tvTeacherWelcome.setText("Teacher Dashboard");
        }

        cardRegisterStudent.setOnClickListener(v -> startActivity(new Intent(this, StudentRegisterActivity.class)));
        cardMarkAttendance.setOnClickListener(v -> startActivity(new Intent(this, MarkAttendanceActivity.class)));
        cardAddResults.setOnClickListener(v -> startActivity(new Intent(this, AddResultsActivity.class)));
        cardManageSubjects.setOnClickListener(v -> startActivity(new Intent(this, ManageSubjectsActivity.class)));
        cardPostTeacherAnnouncement.setOnClickListener(v -> startActivity(new Intent(this, PostAnnouncementActivity.class)));
        cardManageAnnouncements.setOnClickListener(v -> startActivity(new Intent(this, ManageAnnouncementsActivity.class)));
        cardViewParents.setOnClickListener(v -> startActivity(new Intent(this, ViewParentsActivity.class)));

        loadAnnouncements(teacherGrade);
    }

    private void loadAnnouncements(int teacherGrade) {
        ArrayList<String> announcementList = new ArrayList<>();
        SQLiteDatabase db = dbHelper.getReadableDatabase();

        String selection = DatabaseHelper.ANNOUNCEMENT_GRADE_TARGET + " = ? OR " + DatabaseHelper.ANNOUNCEMENT_GRADE_TARGET + " IS NULL";
        String[] selectionArgs = {String.valueOf(teacherGrade)};

        Cursor cursor = db.query(DatabaseHelper.TABLE_ANNOUNCEMENT, new String[]{DatabaseHelper.ANNOUNCEMENT_TITLE, DatabaseHelper.ANNOUNCEMENT_MESSAGE, DatabaseHelper.ANNOUNCEMENT_SOURCE_LABEL, DatabaseHelper.ANNOUNCEMENT_TIMESTAMP},
                selection, selectionArgs, null, null, DatabaseHelper.ANNOUNCEMENT_TIMESTAMP + " DESC");

        if (cursor != null && cursor.moveToFirst()) {
            do {
                String title = cursor.getString(cursor.getColumnIndexOrThrow(DatabaseHelper.ANNOUNCEMENT_TITLE));
                String message = cursor.getString(cursor.getColumnIndexOrThrow(DatabaseHelper.ANNOUNCEMENT_MESSAGE));
                String source = cursor.getString(cursor.getColumnIndexOrThrow(DatabaseHelper.ANNOUNCEMENT_SOURCE_LABEL));
                String timestamp = cursor.getString(cursor.getColumnIndexOrThrow(DatabaseHelper.ANNOUNCEMENT_TIMESTAMP));

                SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss", Locale.getDefault());
                try {
                    Date date = sdf.parse(timestamp);
                    SimpleDateFormat outputFormat = new SimpleDateFormat("MMM dd, yyyy - hh:mm a", Locale.getDefault());
                    timestamp = outputFormat.format(date);
                } catch (Exception e) {
                    // Keep raw timestamp if parsing fails
                }

                announcementList.add("[" + source + "] " + title + "\n" + message + "\n" + timestamp);
            } while (cursor.moveToNext());
            cursor.close();
        }
        db.close();

        if (announcementList.isEmpty()) {
            announcementList.add("No announcements available right now.");
        }

        ArrayAdapter<String> adapter = new ArrayAdapter<>(this, android.R.layout.simple_list_item_1, announcementList);
        lvTeacherAnnouncements.setAdapter(adapter);
    }

    @Override
    public boolean onCreateOptionsMenu(Menu menu) {
        getMenuInflater().inflate(R.menu.menu_logout, menu);
        return true;
    }

    @Override
    public boolean onOptionsItemSelected(MenuItem item) {
        if (item.getItemId() == R.id.action_logout) {
            logout();
            return true;
        }
        return super.onOptionsItemSelected(item);
    }

    @Override
    public void onBackPressed() {
        // Overriding to do nothing and stay on the dashboard
    }

    private void logout() {
        Intent intent = new Intent(this, LoginActivity.class);
        intent.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TASK);
        startActivity(intent);
        finish();
    }
}

