        cardAddResults = findViewById(R.id.cardAddResults);
        cardManageSubjects = findViewById(R.id.cardManageSubjects);
        cardPostTeacherAnnouncement = findViewById(R.id.cardPostTeacherAnnouncement);
        cardManageAnnouncements = findViewById(R.id.cardManageAnnouncements);
        cardViewParents = findViewById(R.id.cardViewParents);
        lvTeacherAnnouncements = findViewById(R.id.lvTeacherAnnouncements);

        SharedPreferences prefs = getSharedPreferences(LoginActivity.PREFS_NAME, Context.MODE_PRIVATE);
        teacherGrade = prefs.getInt(LoginActivity.KEY_USER_GRADE, -1);

        if (teacherGrade != -1) {
            tvTeacherWelcome.setText("Teacher Dashboard (Grade " + teacherGrade + ")");
        } else {
            tvTeacherWelcome.setText("Teacher Dashboard");
        }

        cardRegisterStudent.setOnClickListener(v -> startActivity(new Intent(this, StudentRegisterActivity.class)));
        cardMarkAttendance.setOnClickListener(v -> startActivity(new Intent(this, MarkAttendanceActivity.class)));
        cardAddResults.setOnClickListener(v -> startActivity(new Intent(this, AddResultsActivity.class)));
        cardManageSubjects.setOnClickListener(v -> startActivity(new Intent(this, ManageSubjectsActivity.class)));
        cardPostTeacherAnnouncement.setOnClickListener(v -> startActivity(new Intent(this, PostAnnouncementActivity.class)));
        cardManageAnnouncements.setOnClickListener(v -> startActivity(new Intent(this, ManageAnnouncementsActivity.class)));
        cardViewParents.setOnClickListener(v -> startActivity(new Intent(this, ViewParentsActivity.class)));

        loadAnnouncements();
    }

    @Override
    protected void onResume() {
        super.onResume();
        loadAnnouncements();
    }

    private void loadAnnouncements() {
        if (teacherGrade == -1) {
            ArrayList<String> errorList = new ArrayList<>();
            errorList.add("Error: Could not load grade information");
            ArrayAdapter<String> adapter = new ArrayAdapter<>(this, android.R.layout.simple_list_item_1, errorList);
            lvTeacherAnnouncements.setAdapter(adapter);
            return;
        }

        ArrayList<String> announcementList = (ArrayList<String>) announcementLoader.loadTeacherAnnouncements(teacherGrade);
        ArrayAdapter<String> adapter = new ArrayAdapter<>(this, android.R.layout.simple_list_item_1, announcementList);
        lvTeacherAnnouncements.setAdapter(adapter);
    }

    private void syncAnnouncements() {
        Toast.makeText(this, "Syncing announcements...", Toast.LENGTH_SHORT).show();

        announcementLoader.syncAnnouncementsFromSupabase((success, message) -> {
            runOnUiThread(() -> {
                if (success) {
                    loadAnnouncements();
                    Toast.makeText(this, "Announcements synced", Toast.LENGTH_SHORT).show();
                } else {
                    Toast.makeText(this, "Sync error: " + message, Toast.LENGTH_SHORT).show();
                }
            });
        });
    }

    @Override
    public boolean onCreateOptionsMenu(Menu menu) {
        getMenuInflater().inflate(R.menu.menu_teacher_dashboard, menu);
        return true;
    }

    @Override
    public boolean onOptionsItemSelected(MenuItem item) {
        int id = item.getItemId();

        if (id == R.id.action_refresh) {
            syncAnnouncements();
            return true;
        } else if (id == R.id.action_logout) {
            logout();
            return true;
        }

        return super.onOptionsItemSelected(item);
    }

    @Override
    public void onBackPressed() {
        // Overriding to do nothing and stay on the dashboard
    }

    private void logout() {
        Intent intent = new Intent(this, LoginActivity.class);
        intent.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK | Intent.FLAG_ACTIVITY_CLEAR_TASK);
        startActivity(intent);
        finish();
    }
}

package com.example.studentintelligentsystem;

import android.content.Context;
import android.content.SharedPreferences;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.os.Bundle;
import android.widget.Toast;

import androidx.appcompat.app.AppCompatActivity;
import androidx.appcompat.widget.Toolbar;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import java.util.ArrayList;
import java.util.List;

public class ViewEditResultsActivity extends AppCompatActivity implements ResultsAdapter.OnResultActionListener {

    private RecyclerView rvResults;
    private ResultsAdapter adapter;
    private DatabaseHelper dbHelper;
    private List<Result> resultsList = new ArrayList<>();

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_view_edit_results);

        Toolbar toolbar = findViewById(R.id.toolbar);
        setSupportActionBar(toolbar);
        getSupportActionBar().setDisplayHomeAsUpEnabled(true);
        getSupportActionBar().setTitle("View & Edit Results");

        dbHelper = new DatabaseHelper(this);
        rvResults = findViewById(R.id.rvResults);
        rvResults.setLayoutManager(new LinearLayoutManager(this));

        loadResults();
    }

    private void loadResults() {
        resultsList.clear();

        SharedPreferences prefs = getSharedPreferences(LoginActivity.PREFS_NAME, Context.MODE_PRIVATE);
        int teacherGrade = prefs.getInt(LoginActivity.KEY_USER_GRADE, -1);
        int teacherId = prefs.getInt(LoginActivity.KEY_USER_ID, -1);

        if (teacherGrade == -1 || teacherId == -1) {
            Toast.makeText(this, "Unable to load results for your grade", Toast.LENGTH_SHORT).show();
            return;
        }

        SQLiteDatabase db = dbHelper.getReadableDatabase();

        // Query to get all results for students in the teacher's grade
        String query = "SELECT r." + DatabaseHelper.RESULT_ID + ", " +
                "r." + DatabaseHelper.RESULT_SUBJECT + ", " +
                "r." + DatabaseHelper.RESULT_TERM + ", " +
                "r." + DatabaseHelper.RESULT_MARKS + ", " +
                "r." + DatabaseHelper.RESULT_COMMENT + ", " +
                "s." + DatabaseHelper.STUDENT_NAME + ", " +
                "s." + DatabaseHelper.STUDENT_ID +
                " FROM " + DatabaseHelper.TABLE_RESULTS + " r " +
                "INNER JOIN " + DatabaseHelper.TABLE_STUDENT + " s ON r." +
                DatabaseHelper.RESULT_FK_STUDENT_ID + " = s." + DatabaseHelper.STUDENT_ID +
                " WHERE s." + DatabaseHelper.STUDENT_GRADE + " = ? " +
                " ORDER BY s." + DatabaseHelper.STUDENT_NAME + " ASC, r." +
                DatabaseHelper.RESULT_SUBJECT + " ASC, r." + DatabaseHelper.RESULT_TERM + " ASC";

        Cursor cursor = db.rawQuery(query, new String[]{String.valueOf(teacherGrade)});

        if (cursor != null && cursor.moveToFirst()) {
            do {
                int resultId = cursor.getInt(cursor.getColumnIndexOrThrow(DatabaseHelper.RESULT_ID));
                String subject = cursor.getString(cursor.getColumnIndexOrThrow(DatabaseHelper.RESULT_SUBJECT));
                String term = cursor.getString(cursor.getColumnIndexOrThrow(DatabaseHelper.RESULT_TERM));
                int marks = cursor.getInt(cursor.getColumnIndexOrThrow(DatabaseHelper.RESULT_MARKS));
                String comment = cursor.getString(cursor.getColumnIndexOrThrow(DatabaseHelper.RESULT_COMMENT));
                String studentName = cursor.getString(cursor.getColumnIndexOrThrow(DatabaseHelper.STUDENT_NAME));
                int studentId = cursor.getInt(cursor.getColumnIndexOrThrow(DatabaseHelper.STUDENT_ID));

                Result result = new Result(resultId, studentId, studentName, subject, term, marks, comment);
                resultsList.add(result);
            } while (cursor.moveToNext());
            cursor.close();
        }
        db.close();

        adapter = new ResultsAdapter(resultsList, this);
        rvResults.setAdapter(adapter);

        if (resultsList.isEmpty()) {
            Toast.makeText(this, "No results found for your grade", Toast.LENGTH_SHORT).show();
        }
    }

    @Override
    public void onEditResult(Result result, int position) {
        // Open edit dialog
        EditResultDialog dialog = new EditResultDialog(this, result, updatedResult -> {
            // Update in database with individual parameters
            if (dbHelper.updateResult(
                    updatedResult.getResultId(),
                    updatedResult.getSubject(),
                    updatedResult.getTerm(),
                    updatedResult.getMarks(),
                    updatedResult.getComment())) {
                // Update in list
                resultsList.set(position, updatedResult);
                adapter.notifyItemChanged(position);
                Toast.makeText(this, "Result updated successfully", Toast.LENGTH_SHORT).show();
            } else {
                Toast.makeText(this, "Failed to update result", Toast.LENGTH_SHORT).show();
            }
        });
        dialog.show();
    }

    @Override
    public void onDeleteResult(Result result, int position) {
        // Show confirmation dialog
        new androidx.appcompat.app.AlertDialog.Builder(this)
                .setTitle("Delete Result")
                .setMessage("Are you sure you want to delete this result for " + result.getStudentName() + "?")
                .setPositiveButton("Delete", (dialog, which) -> {
                    if (dbHelper.deleteResult(result.getResultId())) {
                        resultsList.remove(position);
                        adapter.notifyItemRemoved(position);
                        Toast.makeText(this, "Result deleted successfully", Toast.LENGTH_SHORT).show();
                    } else {
                        Toast.makeText(this, "Failed to delete result", Toast.LENGTH_SHORT).show();
                    }
                })
                .setNegativeButton("Cancel", null)
                .show();
    }

    @Override
    public boolean onSupportNavigateUp() {
        onBackPressed();
        return true;
    }
}

package com.example.studentintelligentsystem;

import android.content.Context;
import android.content.SharedPreferences;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.os.Bundle;
import android.widget.ArrayAdapter;
import android.widget.ListView;
import android.widget.Toast;

import androidx.appcompat.app.AppCompatActivity;
import androidx.appcompat.widget.Toolbar;

import java.util.ArrayList;
import java.util.List;

public class ViewTeachersActivity extends AppCompatActivity {

    private ListView lvTeachers;
    private DatabaseHelper dbHelper;
    private int adminId;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_view_teachers);

        Toolbar toolbar = findViewById(R.id.toolbar);
        setSupportActionBar(toolbar);
        getSupportActionBar().setDisplayHomeAsUpEnabled(true);
        getSupportActionBar().setTitle("Registered Teachers");

        dbHelper = new DatabaseHelper(this);
        lvTeachers = findViewById(R.id.lvTeachers);

        SharedPreferences prefs = getSharedPreferences(LoginActivity.PREFS_NAME, Context.MODE_PRIVATE);
        adminId = prefs.getInt(LoginActivity.KEY_USER_ID, -1);

        if (adminId == -1) {
            Toast.makeText(this, "Error: Could not verify your login.", Toast.LENGTH_LONG).show();
            finish();
            return;
        }

        loadTeachers();
    }

    private void loadTeachers() {
        List<String> teacherList = new ArrayList<>();
        SQLiteDatabase db = dbHelper.getReadableDatabase();

        Cursor cursor = db.query(DatabaseHelper.TABLE_TEACHER, new String[]{DatabaseHelper.TEACHER_NAME, DatabaseHelper.TEACHER_EMAIL, DatabaseHelper.TEACHER_GRADE_ASSIGNED},
                DatabaseHelper.TEACHER_FK_ADMIN_ID + " = ?", new String[]{String.valueOf(adminId)}, null, null, null);

        if (cursor != null && cursor.moveToFirst()) {
            do {
                String name = cursor.getString(cursor.getColumnIndexOrThrow(DatabaseHelper.TEACHER_NAME));
                String email = cursor.getString(cursor.getColumnIndexOrThrow(DatabaseHelper.TEACHER_EMAIL));
                int grade = cursor.getInt(cursor.getColumnIndexOrThrow(DatabaseHelper.TEACHER_GRADE_ASSIGNED));
                teacherList.add(name + "\n" + email + "\nGrade: " + grade);
            } while (cursor.moveToNext());
            cursor.close();
        }
        db.close();

        if (teacherList.isEmpty()) {
            teacherList.add("No teachers registered yet.");
        }

        ArrayAdapter<String> adapter = new ArrayAdapter<>(this, android.R.layout.simple_list_item_1, teacherList);
        lvTeachers.setAdapter(adapter);
    }

    @Override
    public boolean onSupportNavigateUp() {
        onBackPressed();
        return true;
    }
}

package com.example.studentintelligentsystem;

import android.content.Context;
import android.content.SharedPreferences;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.os.Bundle;
import android.util.Log;
import android.view.Menu;
import android.view.MenuItem;
import android.widget.ArrayAdapter;
import android.widget.ListView;
import android.widget.Toast;

import androidx.appcompat.app.AppCompatActivity;
import androidx.appcompat.widget.Toolbar;
import androidx.swiperefreshlayout.widget.SwipeRefreshLayout;

import com.example.studentintelligentsystem.supabase.SupabaseClient;
import com.example.studentintelligentsystem.supabase.SupabaseConfig;

import org.json.JSONArray;
import org.json.JSONObject;

import java.util.ArrayList;
import java.util.List;

public class ViewTeachersActivity extends AppCompatActivity {
    private static final String TAG = "ViewTeachersActivity";

    private ListView lvTeachers;
    private SwipeRefreshLayout swipeRefreshLayout;
    private DatabaseHelper dbHelper;
    private int adminId;
    private ArrayAdapter<String> adapter;
    private List<String> teacherList;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_view_teachers);

        Toolbar toolbar = findViewById(R.id.toolbar);
        setSupportActionBar(toolbar);
        getSupportActionBar().setDisplayHomeAsUpEnabled(true);
        getSupportActionBar().setTitle("Registered Teachers");

        dbHelper = new DatabaseHelper(this);
        lvTeachers = findViewById(R.id.lvTeachers);
        swipeRefreshLayout = findViewById(R.id.swipeRefreshLayout);

        SharedPreferences prefs = getSharedPreferences(LoginActivity.PREFS_NAME, Context.MODE_PRIVATE);
        adminId = prefs.getInt(LoginActivity.KEY_USER_ID, -1);

        if (adminId == -1) {
            Toast.makeText(this, "Error: Could not verify your login.", Toast.LENGTH_LONG).show();
            finish();
            return;
        }

        teacherList = new ArrayList<>();
        adapter = new ArrayAdapter<>(this, android.R.layout.simple_list_item_1, teacherList);
        lvTeachers.setAdapter(adapter);

        // Setup swipe to refresh
        swipeRefreshLayout.setOnRefreshListener(() -> {
            loadTeachersFromSupabase();
        });

        loadTeachers();
    }

    private void loadTeachers() {
        loadTeachersFromLocal();

        // Also try to load from Supabase in background
        if (SupabaseConfig.isConfigured()) {
            loadTeachersFromSupabase();
        }
    }

    private void loadTeachersFromLocal() {
        teacherList.clear();
        SQLiteDatabase db = dbHelper.getReadableDatabase();

        // Load all teachers (not just for this admin, to show synchronized teachers too)
        Cursor cursor = db.query(
                DatabaseHelper.TABLE_TEACHER,
                new String[]{
                    DatabaseHelper.TEACHER_NAME,
                    DatabaseHelper.TEACHER_EMAIL,
                    DatabaseHelper.TEACHER_GRADE_ASSIGNED,
                    DatabaseHelper.TEACHER_FK_ADMIN_ID
                },
                null, // Load all teachers
                null,
                null, null,
                DatabaseHelper.TEACHER_NAME + " ASC"
        );

        if (cursor != null && cursor.moveToFirst()) {
            do {
                String name = cursor.getString(cursor.getColumnIndexOrThrow(DatabaseHelper.TEACHER_NAME));
                String email = cursor.getString(cursor.getColumnIndexOrThrow(DatabaseHelper.TEACHER_EMAIL));
                int grade = cursor.getInt(cursor.getColumnIndexOrThrow(DatabaseHelper.TEACHER_GRADE_ASSIGNED));
                int teacherAdminId = cursor.getInt(cursor.getColumnIndexOrThrow(DatabaseHelper.TEACHER_FK_ADMIN_ID));

                String adminIndicator = (teacherAdminId == adminId) ? " ★" : "";
                teacherList.add(name + adminIndicator + "\n" + email + "\nGrade: " + grade);
            } while (cursor.moveToNext());
            cursor.close();
        }
        db.close();

        if (teacherList.isEmpty()) {
            teacherList.add("No teachers registered yet.\nPull down to refresh from cloud.");
        }

        adapter.notifyDataSetChanged();
    }

    private void loadTeachersFromSupabase() {
        if (!SupabaseConfig.isConfigured()) {
            if (swipeRefreshLayout != null) {
                swipeRefreshLayout.setRefreshing(false);
            }
            return;
        }

        new Thread(() -> {
            try {
                SupabaseClient client = SupabaseClient.getInstance();
                String response = client.queryData("teachers", "select=*&order=name.asc");

                if (response != null) {
                    JSONArray teachers = new JSONArray(response);
                    Log.d(TAG, "✓ Loaded " + teachers.length() + " teachers from Supabase");

                    // Sync to local database
                    syncTeachersToLocal(teachers);

                    runOnUiThread(() -> {
                        loadTeachersFromLocal();
                        if (swipeRefreshLayout != null) {
                            swipeRefreshLayout.setRefreshing(false);
                        }
                        Toast.makeText(this, "Teachers synced from cloud", Toast.LENGTH_SHORT).show();
                    });
                } else {
                    runOnUiThread(() -> {
                        if (swipeRefreshLayout != null) {
                            swipeRefreshLayout.setRefreshing(false);
                        }
                        Toast.makeText(this, "Could not load from cloud", Toast.LENGTH_SHORT).show();
                    });
                }
            } catch (Exception e) {
                Log.e(TAG, "Error loading teachers from Supabase: " + e.getMessage());
                runOnUiThread(() -> {
                    if (swipeRefreshLayout != null) {
                        swipeRefreshLayout.setRefreshing(false);
                    }
                    Toast.makeText(this, "Sync error: " + e.getMessage(), Toast.LENGTH_SHORT).show();
                });
            }
        }).start();
    }

    private void syncTeachersToLocal(JSONArray teachers) {
        try {
            SQLiteDatabase db = dbHelper.getWritableDatabase();

            for (int i = 0; i < teachers.length(); i++) {
                JSONObject teacher = teachers.getJSONObject(i);

                android.content.ContentValues values = new android.content.ContentValues();
                values.put(DatabaseHelper.TEACHER_ID, teacher.getInt("id"));
                values.put(DatabaseHelper.TEACHER_NAME, teacher.getString("name"));
                values.put(DatabaseHelper.TEACHER_EMAIL, teacher.getString("email"));
                values.put(DatabaseHelper.TEACHER_PASSWORD, teacher.getString("password_hash"));
                values.put(DatabaseHelper.TEACHER_GRADE_ASSIGNED, teacher.getInt("grade_assigned"));
                values.put(DatabaseHelper.TEACHER_FK_ADMIN_ID, teacher.getInt("admin_id"));

                db.insertWithOnConflict(DatabaseHelper.TABLE_TEACHER, null, values,
                        SQLiteDatabase.CONFLICT_REPLACE);
            }

            db.close();
            Log.d(TAG, "✓ Synced " + teachers.length() + " teachers to local database");
        } catch (Exception e) {
            Log.e(TAG, "Error syncing teachers to local: " + e.getMessage());
        }
    }

    @Override
    public boolean onCreateOptionsMenu(Menu menu) {
        getMenuInflater().inflate(R.menu.menu_refresh, menu);
        return true;
    }

    @Override
    public boolean onOptionsItemSelected(MenuItem item) {
        if (item.getItemId() == R.id.action_refresh) {
            swipeRefreshLayout.setRefreshing(true);
            loadTeachersFromSupabase();
            return true;
        }
        return super.onOptionsItemSelected(item);
    }

    @Override
    public boolean onSupportNavigateUp() {
        onBackPressed();
        return true;
    }
}

package com.example.studentintelligentsystem.data;

import android.os.Handler;
import android.os.Looper;
import android.util.Log;

import com.example.studentintelligentsystem.BuildConfig;

import org.json.JSONArray;
import org.json.JSONObject;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * Repository for managing results with Supabase backend
 */
public class ResultsRepository {
    private static final String TAG = "ResultsRepository";
    private final ExecutorService executor = Executors.newSingleThreadExecutor();
    private final Handler mainHandler = new Handler(Looper.getMainLooper());

    public interface UpdateCallback {
        void onSuccess(JSONObject updatedResult);
        void onError(String error);
    }

    /**
     * Update a result in Supabase
     */
    public void updateResult(int resultId, String subjectName, String term, int marks, String comment, UpdateCallback callback) {
        executor.execute(() -> {
            try {
                String url = BuildConfig.SUPABASE_URL.replaceAll("/$", "") + "/rest/v1/results?id=eq." + resultId;

                JSONObject json = new JSONObject();
                json.put("subject_name", subjectName);
                json.put("term", term);
                json.put("marks", marks);
                json.put("comment", comment);

                HttpURLConnection conn = (HttpURLConnection) new URL(url).openConnection();
                conn.setRequestMethod("PATCH");
                conn.setRequestProperty("apikey", BuildConfig.SUPABASE_ANON_KEY);
                conn.setRequestProperty("Authorization", "Bearer " + BuildConfig.SUPABASE_ANON_KEY);
                conn.setRequestProperty("Content-Type", "application/json");
                conn.setRequestProperty("Prefer", "return=representation");
                conn.setDoOutput(true);

                OutputStream os = conn.getOutputStream();
                os.write(json.toString().getBytes("UTF-8"));
                os.flush();
                os.close();

                int responseCode = conn.getResponseCode();

                if (responseCode == 200 || responseCode == 204) {
                    BufferedReader br = new BufferedReader(new InputStreamReader(conn.getInputStream()));
                    StringBuilder response = new StringBuilder();
                    String line;
                    while ((line = br.readLine()) != null) {
                        response.append(line);
                    }
                    br.close();
                    conn.disconnect();

                    String responseBody = response.toString();
                    if (responseBody.isEmpty() || responseBody.equals("[]")) {
                        // Success but no representation returned
                        mainHandler.post(() -> callback.onSuccess(json));
                    } else {
                        JSONArray arr = new JSONArray(responseBody);
                        if (arr.length() > 0) {
                            JSONObject updated = arr.getJSONObject(0);
                            mainHandler.post(() -> callback.onSuccess(updated));
                        } else {
                            mainHandler.post(() -> callback.onSuccess(json));
                        }
                    }
                } else {
                    BufferedReader br = new BufferedReader(new InputStreamReader(conn.getErrorStream()));
                    StringBuilder errorResponse = new StringBuilder();
                    String line;
                    while ((line = br.readLine()) != null) {
                        errorResponse.append(line);
                    }
                    br.close();
                    conn.disconnect();

                    String errorMsg = "Update failed: " + responseCode + " - " + errorResponse.toString();
                    Log.e(TAG, errorMsg);
                    mainHandler.post(() -> callback.onError(errorMsg));
                }
            } catch (Exception e) {
                Log.e(TAG, "Exception updating result", e);
                mainHandler.post(() -> callback.onError("Exception: " + e.getMessage()));
            }
        });
    }
}

package com.example.studentintelligentsystem.supabase;

import android.util.Log;
import org.json.JSONArray;
import org.json.JSONObject;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;

/**
 * Supabase Authentication Manager
 * Handles login by querying Supabase database for user credentials
 */
public class SupabaseAuthManager {
    private static final String TAG = "SupabaseAuthManager";

    public SupabaseAuthManager() {
        // Empty constructor
    }

    /**
     * Login user by querying Supabase
     * @param email User's email
     * @param password User's plaintext password (will be hashed)
     * @param role User role: Admin, Teacher, or Parent
     * @return JSONObject with user data if login successful, null otherwise
     */
    public JSONObject login(String email, String password, String role) {
        if (!SupabaseConfig.isConfigured()) {
            Log.e(TAG, "Supabase not configured");
            return null;
        }

        try {
            // Hash password to match stored hash
            String hashedPassword = hashPassword(password);

            // Determine table name based on role
            String tableName = getTableNameForRole(role);
            if (tableName == null) {
                Log.e(TAG, "Invalid role: " + role);
                return null;
            }

            Log.d(TAG, "Attempting login for " + role + " with email: " + email);

            // Query Supabase for user
            String urlString = SupabaseConfig.SUPABASE_URL + "/rest/v1/" + tableName
                + "?email=eq." + email
                + "&password_hash=eq." + hashedPassword
                + "&select=*";

            URL url = new URL(urlString);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();

            conn.setRequestMethod("GET");
            conn.setRequestProperty("apikey", SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Authorization", "Bearer " + SupabaseConfig.SUPABASE_ANON_KEY);

            int responseCode = conn.getResponseCode();

            if (responseCode == 200) {
                BufferedReader br = new BufferedReader(new InputStreamReader(conn.getInputStream()));
                StringBuilder response = new StringBuilder();
                String line;
                while ((line = br.readLine()) != null) {
                    response.append(line);
                }
                br.close();

                // Parse response
                JSONArray users = new JSONArray(response.toString());

                if (users.length() > 0) {
                    JSONObject user = users.getJSONObject(0);
                    Log.i(TAG, "✓ Login successful for " + role + ": " + email);
                    return user;
                } else {
                    Log.w(TAG, "✗ Login failed: Invalid credentials for " + role);
                    return null;
                }

            } else {
                Log.e(TAG, "✗ Login failed: HTTP " + responseCode);
                return null;
            }

        } catch (Exception e) {
            Log.e(TAG, "Error during login: " + e.getMessage(), e);
            return null;
        }
    }

    /**
     * Get table name based on user role
     */
    private String getTableNameForRole(String role) {
        switch (role) {
            case "Admin":
                return "admins";
            case "Teacher":
                return "teachers";
            case "Parent":
                return "parents";
            default:
                return null;
        }
    }

    /**
     * Hash password using SHA-256
     * Must match the hashing in DatabaseHelper
     */
    private String hashPassword(String password) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(password.getBytes(StandardCharsets.UTF_8));
            StringBuilder hexString = new StringBuilder();
            for (byte b : hash) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (Exception e) {
            Log.e(TAG, "Error hashing password", e);
            return null;
        }
    }
}

package com.example.studentintelligentsystem.supabase;

import android.content.Context;
import android.util.Log;
import org.json.JSONObject;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.concurrent.atomic.AtomicReference;

/**
 * Supabase Client Singleton
 * Handles all communication with Supabase backend
 */
public class SupabaseClient {
    private static final String TAG = "SupabaseClient";
    private static SupabaseClient instance;
    private Context context;
    private boolean isInitialized = false;

    private SupabaseClient(Context context) {
        this.context = context.getApplicationContext();
    }

    /**
     * Initialize the Supabase client
     */
    public static synchronized void initialize(Context context) {
        if (instance == null) {
            instance = new SupabaseClient(context);
            instance.isInitialized = true;
            Log.d(TAG, "SupabaseClient initialized");
        }
    }

    /**
     * Get the singleton instance
     */
    public static synchronized SupabaseClient getInstance() {
        if (instance == null) {
            throw new IllegalStateException("SupabaseClient not initialized. Call initialize() first.");
        }
        return instance;
    }

    /**
     * Test connection to Supabase
     */
    public boolean testConnection() {
        if (!SupabaseConfig.isConfigured()) {
            Log.e(TAG, "Cannot test connection: Supabase not configured");
            return false;
        }

        try {
            // Try to query the profiles table (should exist)
            String urlString = SupabaseConfig.SUPABASE_URL + "/rest/v1/profiles?limit=1";
            URL url = new URL(urlString);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();

            conn.setRequestMethod("GET");
            conn.setRequestProperty("apikey", SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Authorization", "Bearer " + SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setConnectTimeout(5000);
            conn.setReadTimeout(5000);

            int responseCode = conn.getResponseCode();
            conn.disconnect();

            Log.d(TAG, "Connection test response code: " + responseCode);
            return responseCode == 200 || responseCode == 201;

        } catch (Exception e) {
            Log.e(TAG, "Connection test failed: " + e.getMessage());
            return false;
        }
    }

    /**
     * Insert data into Supabase table
     */
    public boolean insertData(String tableName, JSONObject data) {
        if (!isInitialized || !SupabaseConfig.isConfigured()) {
            Log.e(TAG, "Cannot insert: Supabase not properly initialized");
            return false;
        }

        try {
            String urlString = SupabaseConfig.SUPABASE_URL + "/rest/v1/" + tableName;
            URL url = new URL(urlString);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();

            conn.setRequestMethod("POST");
            conn.setRequestProperty("Content-Type", "application/json");
            conn.setRequestProperty("apikey", SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Authorization", "Bearer " + SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Prefer", "return=representation");
            conn.setDoOutput(true);

            // Write JSON data
            OutputStream os = conn.getOutputStream();
            os.write(data.toString().getBytes("UTF-8"));
            os.flush();
            os.close();

            int responseCode = conn.getResponseCode();

            if (responseCode == 200 || responseCode == 201) {
                Log.d(TAG, "Data inserted successfully to " + tableName);
                return true;
            } else {
                BufferedReader br = new BufferedReader(new InputStreamReader(conn.getErrorStream()));
                StringBuilder response = new StringBuilder();
                String line;
                while ((line = br.readLine()) != null) {
                    response.append(line);
                }
                br.close();
                Log.e(TAG, "Insert failed: " + responseCode + " - " + response.toString());
                return false;
            }

        } catch (Exception e) {
            Log.e(TAG, "Error inserting data to " + tableName + ": " + e.getMessage(), e);
            return false;
        }
    }

    /**
     * Update data in Supabase table
     */
    public boolean updateData(String tableName, String idColumn, String idValue, JSONObject data) {
        if (!isInitialized || !SupabaseConfig.isConfigured()) {
            Log.e(TAG, "Cannot update: Supabase not properly initialized");
            return false;
        }

        try {
            String urlString = SupabaseConfig.SUPABASE_URL + "/rest/v1/" + tableName + "?" + idColumn + "=eq." + idValue;
            URL url = new URL(urlString);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();

            conn.setRequestMethod("PATCH");
            conn.setRequestProperty("Content-Type", "application/json");
            conn.setRequestProperty("apikey", SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Authorization", "Bearer " + SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Prefer", "return=representation");
            conn.setDoOutput(true);

            OutputStream os = conn.getOutputStream();
            os.write(data.toString().getBytes("UTF-8"));
            os.flush();
            os.close();

            int responseCode = conn.getResponseCode();

            if (responseCode == 200 || responseCode == 204) {
                Log.d(TAG, "Data updated successfully in " + tableName);
                return true;
            } else {
                Log.e(TAG, "Update failed: " + responseCode);
                return false;
            }

        } catch (Exception e) {
            Log.e(TAG, "Error updating data in " + tableName + ": " + e.getMessage(), e);
            return false;
        }
    }

    /**
     * Query data from Supabase table
     */
    public String queryData(String tableName, String filter) {
        if (!isInitialized || !SupabaseConfig.isConfigured()) {
            Log.e(TAG, "Cannot query: Supabase not properly initialized");
            return null;
        }

        try {
            String urlString = SupabaseConfig.SUPABASE_URL + "/rest/v1/" + tableName;
            if (filter != null && !filter.isEmpty()) {
                urlString += "?" + filter;
            }

            URL url = new URL(urlString);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();

            conn.setRequestMethod("GET");
            conn.setRequestProperty("apikey", SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Authorization", "Bearer " + SupabaseConfig.SUPABASE_ANON_KEY);

            int responseCode = conn.getResponseCode();

            if (responseCode == 200) {
                BufferedReader br = new BufferedReader(new InputStreamReader(conn.getInputStream()));
                StringBuilder response = new StringBuilder();
                String line;
                while ((line = br.readLine()) != null) {
                    response.append(line);
                }
                br.close();
                return response.toString();
            } else {
                Log.e(TAG, "Query failed: " + responseCode);
                return null;
            }

        } catch (Exception e) {
            Log.e(TAG, "Error querying data from " + tableName + ": " + e.getMessage(), e);
            return null;
        }
    }

    public boolean isInitialized() {
        return isInitialized;
    }
}

package com.example.studentintelligentsystem.supabase;

import android.content.Context;
import android.util.Log;
import org.json.JSONObject;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.concurrent.atomic.AtomicReference;

/**
 * Supabase Client Singleton
 * Handles all communication with Supabase backend
 */
public class SupabaseClient {
    private static final String TAG = "SupabaseClient";
    private static SupabaseClient instance;
    private Context context;
    private boolean isInitialized = false;

    private SupabaseClient(Context context) {
        this.context = context.getApplicationContext();
    }

    /**
     * Initialize the Supabase client
     */
    public static synchronized void initialize(Context context) {
        if (instance == null) {
            instance = new SupabaseClient(context);
            instance.isInitialized = true;
            Log.d(TAG, "SupabaseClient initialized");
        }
    }

    /**
     * Get the singleton instance
     */
    public static synchronized SupabaseClient getInstance() {
        if (instance == null) {
            throw new IllegalStateException("SupabaseClient not initialized. Call initialize() first.");
        }
        return instance;
    }

    /**
     * Test connection to Supabase
     */
    public boolean testConnection() {
        if (!SupabaseConfig.isConfigured()) {
            Log.e(TAG, "Cannot test connection: Supabase not configured");
            return false;
        }

        try {
            // Try to query the profiles table (should exist)
            String urlString = SupabaseConfig.SUPABASE_URL + "/rest/v1/profiles?limit=1";
            URL url = new URL(urlString);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();

            conn.setRequestMethod("GET");
            conn.setRequestProperty("apikey", SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Authorization", "Bearer " + SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setConnectTimeout(5000);
            conn.setReadTimeout(5000);

            int responseCode = conn.getResponseCode();
            conn.disconnect();

            Log.d(TAG, "Connection test response code: " + responseCode);
            return responseCode == 200 || responseCode == 201;

        } catch (Exception e) {
            Log.e(TAG, "Connection test failed: " + e.getMessage());
            return false;
        }
    }

    /**
     * Intelligent UPSERT: Insert if not exists, update if exists
     * Prevents duplicate key errors (409)
     */
    public boolean upsertData(String tableName, JSONObject data) {
        if (!isInitialized || !SupabaseConfig.isConfigured()) {
            Log.e(TAG, "Cannot upsert: Supabase not properly initialized");
            return false;
        }

        try {
            // Use Supabase's UPSERT feature with Prefer header
            String urlString = SupabaseConfig.SUPABASE_URL + "/rest/v1/" + tableName;
            URL url = new URL(urlString);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();

            conn.setRequestMethod("POST");
            conn.setRequestProperty("Content-Type", "application/json");
            conn.setRequestProperty("apikey", SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Authorization", "Bearer " + SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Prefer", "resolution=merge-duplicates,return=representation");
            conn.setDoOutput(true);

            // Write JSON data
            OutputStream os = conn.getOutputStream();
            os.write(data.toString().getBytes("UTF-8"));
            os.flush();
            os.close();

            int responseCode = conn.getResponseCode();

            if (responseCode == 200 || responseCode == 201) {
                Log.d(TAG, "Data upserted successfully to " + tableName);
                return true;
            } else if (responseCode == 409) {
                // Conflict - try update instead
                Log.d(TAG, "Record exists, attempting update for " + tableName);
                if (data.has("id")) {
                    return updateData(tableName, "id", String.valueOf(data.get("id")), data);
                } else {
                    Log.w(TAG, "Cannot update: no 'id' field in data");
                    return false;
                }
            } else {
                BufferedReader br = new BufferedReader(new InputStreamReader(conn.getErrorStream()));
                StringBuilder response = new StringBuilder();
                String line;
                while ((line = br.readLine()) != null) {
                    response.append(line);
                }
                br.close();
                Log.e(TAG, "Upsert failed: " + responseCode + " - " + response.toString());
                return false;
            }

        } catch (Exception e) {
            Log.e(TAG, "Error upserting data to " + tableName + ": " + e.getMessage(), e);
            return false;
        }
    }

    /**
     * Insert data into Supabase table
     * @deprecated Use upsertData() instead to avoid duplicate key errors
     */
    public boolean insertData(String tableName, JSONObject data) {
        // Redirect to upsert for intelligent handling
        return upsertData(tableName, data);
    }

    /**
     * Update data in Supabase table
     */
    public boolean updateData(String tableName, String idColumn, String idValue, JSONObject data) {
        if (!isInitialized || !SupabaseConfig.isConfigured()) {
            Log.e(TAG, "Cannot update: Supabase not properly initialized");
            return false;
        }

        try {
            String urlString = SupabaseConfig.SUPABASE_URL + "/rest/v1/" + tableName + "?" + idColumn + "=eq." + idValue;
            URL url = new URL(urlString);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();

            conn.setRequestMethod("PATCH");
            conn.setRequestProperty("Content-Type", "application/json");
            conn.setRequestProperty("apikey", SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Authorization", "Bearer " + SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Prefer", "return=representation");
            conn.setDoOutput(true);

            OutputStream os = conn.getOutputStream();
            os.write(data.toString().getBytes("UTF-8"));
            os.flush();
            os.close();

            int responseCode = conn.getResponseCode();

            if (responseCode == 200 || responseCode == 204) {
                Log.d(TAG, "Data updated successfully in " + tableName);
                return true;
            } else {
                Log.e(TAG, "Update failed: " + responseCode);
                return false;
            }

        } catch (Exception e) {
            Log.e(TAG, "Error updating data in " + tableName + ": " + e.getMessage(), e);
            return false;
        }
    }

    /**
     * Query data from Supabase table
     */
    public String queryData(String tableName, String filter) {
        if (!isInitialized || !SupabaseConfig.isConfigured()) {
            Log.e(TAG, "Cannot query: Supabase not properly initialized");
            return null;
        }

        try {
            String urlString = SupabaseConfig.SUPABASE_URL + "/rest/v1/" + tableName;
            if (filter != null && !filter.isEmpty()) {
                urlString += "?" + filter;
            }

            URL url = new URL(urlString);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();

            conn.setRequestMethod("GET");
            conn.setRequestProperty("apikey", SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Authorization", "Bearer " + SupabaseConfig.SUPABASE_ANON_KEY);

            int responseCode = conn.getResponseCode();

            if (responseCode == 200) {
                BufferedReader br = new BufferedReader(new InputStreamReader(conn.getInputStream()));
                StringBuilder response = new StringBuilder();
                String line;
                while ((line = br.readLine()) != null) {
                    response.append(line);
                }
                br.close();
                return response.toString();
            } else {
                Log.e(TAG, "Query failed: " + responseCode);
                return null;
            }

        } catch (Exception e) {
            Log.e(TAG, "Error querying data from " + tableName + ": " + e.getMessage(), e);
            return null;
        }
    }

    public boolean isInitialized() {
        return isInitialized;
    }

    /**
     * Query parent by email from Supabase
     * Returns the parent JSON object if found, null otherwise
     */
    public JSONObject getParentByEmail(String email) {
        if (!isInitialized || !SupabaseConfig.isConfigured()) {
            Log.e(TAG, "Cannot query parent: Supabase not properly initialized");
            return null;
        }

        try {
            String urlString = SupabaseConfig.SUPABASE_URL + "/rest/v1/parents?email=eq." + email;
            URL url = new URL(urlString);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();

            conn.setRequestMethod("GET");
            conn.setRequestProperty("apikey", SupabaseConfig.SUPABASE_ANON_KEY);
            conn.setRequestProperty("Authorization", "Bearer " + SupabaseConfig.SUPABASE_ANON_KEY);

            int responseCode = conn.getResponseCode();

            if (responseCode == 200) {
                BufferedReader br = new BufferedReader(new InputStreamReader(conn.getInputStream()));
                StringBuilder response = new StringBuilder();
                String line;
                while ((line = br.readLine()) != null) {
                    response.append(line);
                }
                br.close();

                // Parse response as JSON array
                String jsonResponse = response.toString();
                org.json.JSONArray jsonArray = new org.json.JSONArray(jsonResponse);

                if (jsonArray.length() > 0) {
                    Log.d(TAG, "✓ Parent found in Supabase with email: " + email);
                    return jsonArray.getJSONObject(0);
                } else {
                    Log.d(TAG, "No parent found in Supabase with email: " + email);
                    return null;
                }
            } else {
                Log.e(TAG, "Query parent by email failed: " + responseCode);
                return null;
            }

        } catch (Exception e) {
            Log.e(TAG, "Error querying parent by email: " + e.getMessage(), e);
            return null;
        }
    }
}

-- Drop All Tables Script
-- Run this FIRST to clean up before running the migration

-- Drop tables in reverse dependency order
DROP TABLE IF EXISTS sync_logs CASCADE;
DROP TABLE IF EXISTS announcements CASCADE;
DROP TABLE IF EXISTS subjects CASCADE;
DROP TABLE IF EXISTS results CASCADE;
DROP TABLE IF EXISTS attendance CASCADE;
DROP TABLE IF EXISTS students CASCADE;
DROP TABLE IF EXISTS parents CASCADE;
DROP TABLE IF EXISTS teachers CASCADE;
DROP TABLE IF EXISTS admins CASCADE;
DROP TABLE IF EXISTS profiles CASCADE;

-- Drop any existing policies
DROP POLICY IF EXISTS "Admins can view themselves" ON admins;
DROP POLICY IF EXISTS "Teachers can view themselves" ON teachers;
DROP POLICY IF EXISTS "Parents can view themselves" ON parents;
DROP POLICY IF EXISTS "Teachers can view students in their grade" ON students;
DROP POLICY IF EXISTS "Teachers can view attendance for their students" ON attendance;
DROP POLICY IF EXISTS "Teachers and parents can view results" ON results;
DROP POLICY IF EXISTS "Subjects are viewable" ON subjects;
DROP POLICY IF EXISTS "Announcements are viewable" ON announcements;

-- Success message
SELECT 'All tables dropped successfully! Now run supabase_migration_fixed.sql' AS status;

-- Supabase SQL Schema for Student Intelligent System
-- FIXED VERSION - Tables created in correct dependency order
-- Run this AFTER running supabase_drop_all.sql

-- Enable required extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- ============================================
-- STEP 1: Create base tables (no dependencies)
-- ============================================

-- Create profiles table (for users)
CREATE TABLE IF NOT EXISTS profiles (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    email TEXT UNIQUE,
    user_type TEXT CHECK (user_type IN ('admin', 'teacher', 'parent', 'student')),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Create admins table (no dependencies)
CREATE TABLE IF NOT EXISTS admins (
    id SERIAL PRIMARY KEY,
    school_name TEXT NOT NULL,
    district TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- ============================================
-- STEP 2: Create tables that depend on admins
-- ============================================

-- Create teachers table (depends on admins)
CREATE TABLE IF NOT EXISTS teachers (
    id SERIAL PRIMARY KEY,
    name TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    grade_assigned INT NOT NULL,
    admin_id INT NOT NULL REFERENCES admins(id) ON DELETE CASCADE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Create parents table (depends on admins)
CREATE TABLE IF NOT EXISTS parents (
    id SERIAL PRIMARY KEY,
    name TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    phone TEXT,
    password_hash TEXT NOT NULL,
    admin_id INT NOT NULL REFERENCES admins(id) ON DELETE CASCADE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- ============================================
-- STEP 3: Create tables that depend on teachers/parents
-- ============================================

-- Create students table (depends on parents and teachers)
CREATE TABLE IF NOT EXISTS students (
    id SERIAL PRIMARY KEY,
    name TEXT NOT NULL,
    age INT,
    gender TEXT,
    grade INT NOT NULL,
    address TEXT,
    parent_id INT NOT NULL REFERENCES parents(id) ON DELETE CASCADE,
    teacher_id INT NOT NULL REFERENCES teachers(id) ON DELETE CASCADE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- ============================================
-- STEP 4: Create tables that depend on students
-- ============================================

-- Create attendance table (depends on students and teachers)
CREATE TABLE IF NOT EXISTS attendance (
    id SERIAL PRIMARY KEY,
    student_id INT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    date DATE NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('Present', 'Absent')),
    teacher_id INT NOT NULL REFERENCES teachers(id) ON DELETE CASCADE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(student_id, date)
);

-- Create results table (depends on students and teachers)
CREATE TABLE IF NOT EXISTS results (
    id SERIAL PRIMARY KEY,
    student_id INT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
    subject_name TEXT NOT NULL,
    term TEXT NOT NULL,
    marks INT NOT NULL CHECK (marks >= 0 AND marks <= 100),
    comment TEXT,
    teacher_id INT NOT NULL REFERENCES teachers(id) ON DELETE CASCADE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Create subjects table (depends on teachers)
CREATE TABLE IF NOT EXISTS subjects (
    id SERIAL PRIMARY KEY,
    name TEXT NOT NULL,
    grade INT NOT NULL,
    teacher_id INT NOT NULL REFERENCES teachers(id) ON DELETE CASCADE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(name, grade, teacher_id)
);

-- ============================================
-- STEP 5: Create independent utility tables
-- ============================================

-- Create announcements table (no foreign key dependencies)
CREATE TABLE IF NOT EXISTS announcements (
    id SERIAL PRIMARY KEY,
    title TEXT NOT NULL,
    message TEXT NOT NULL,
    created_by_role TEXT NOT NULL CHECK (created_by_role IN ('admin', 'teacher')),
    created_by_id INT NOT NULL,
    grade_target INT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Create sync log table for tracking data synchronization
CREATE TABLE IF NOT EXISTS sync_logs (
    id SERIAL PRIMARY KEY,
    table_name TEXT NOT NULL,
    record_id INT NOT NULL,
    action TEXT NOT NULL CHECK (action IN ('INSERT', 'UPDATE', 'DELETE')),
    sync_status TEXT NOT NULL CHECK (sync_status IN ('pending', 'success', 'failed')),
    error_message TEXT,
    synced_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- ============================================
-- STEP 6: Create indexes for better performance
-- ============================================

CREATE INDEX IF NOT EXISTS idx_teachers_admin_id ON teachers(admin_id);
CREATE INDEX IF NOT EXISTS idx_parents_admin_id ON parents(admin_id);
CREATE INDEX IF NOT EXISTS idx_students_parent_id ON students(parent_id);
CREATE INDEX IF NOT EXISTS idx_students_teacher_id ON students(teacher_id);
CREATE INDEX IF NOT EXISTS idx_students_grade ON students(grade);
CREATE INDEX IF NOT EXISTS idx_attendance_student_id ON attendance(student_id);
CREATE INDEX IF NOT EXISTS idx_attendance_date ON attendance(date);
CREATE INDEX IF NOT EXISTS idx_attendance_teacher_id ON attendance(teacher_id);
CREATE INDEX IF NOT EXISTS idx_results_student_id ON results(student_id);
CREATE INDEX IF NOT EXISTS idx_results_teacher_id ON results(teacher_id);
CREATE INDEX IF NOT EXISTS idx_subjects_grade ON subjects(grade);
CREATE INDEX IF NOT EXISTS idx_subjects_teacher_id ON subjects(teacher_id);
CREATE INDEX IF NOT EXISTS idx_announcements_created_by_id ON announcements(created_by_id);
CREATE INDEX IF NOT EXISTS idx_sync_logs_status ON sync_logs(sync_status);
CREATE INDEX IF NOT EXISTS idx_sync_logs_table ON sync_logs(table_name);

-- ============================================
-- STEP 7: Enable Row Level Security (RLS)
-- ============================================

ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE admins ENABLE ROW LEVEL SECURITY;
ALTER TABLE teachers ENABLE ROW LEVEL SECURITY;
ALTER TABLE parents ENABLE ROW LEVEL SECURITY;
ALTER TABLE students ENABLE ROW LEVEL SECURITY;
ALTER TABLE attendance ENABLE ROW LEVEL SECURITY;
ALTER TABLE results ENABLE ROW LEVEL SECURITY;
ALTER TABLE subjects ENABLE ROW LEVEL SECURITY;
ALTER TABLE announcements ENABLE ROW LEVEL SECURITY;

-- ============================================
-- STEP 8: Create RLS policies
-- ============================================

-- Admins can view their own records
CREATE POLICY "Admins can view themselves" ON admins
    FOR SELECT USING (TRUE);

-- Teachers can view themselves
CREATE POLICY "Teachers can view themselves" ON teachers
    FOR SELECT USING (TRUE);

-- Parents can view themselves
CREATE POLICY "Parents can view themselves" ON parents
    FOR SELECT USING (TRUE);

-- Students data is viewable by teachers and parents
CREATE POLICY "Teachers can view students in their grade" ON students
    FOR SELECT USING (TRUE);

-- Attendance data is viewable by teachers and parents
CREATE POLICY "Teachers can view attendance for their students" ON attendance
    FOR SELECT USING (TRUE);

-- Results are viewable by teachers and parents
CREATE POLICY "Teachers and parents can view results" ON results
    FOR SELECT USING (TRUE);

-- Subjects are viewable by all
CREATE POLICY "Subjects are viewable" ON subjects
    FOR SELECT USING (TRUE);

-- Announcements are viewable by all
CREATE POLICY "Announcements are viewable" ON announcements
    FOR SELECT USING (TRUE);

-- ============================================
-- STEP 9: Grant permissions
-- ============================================

GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO anon;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO anon;

-- ============================================
-- STEP 10: Add table comments
-- ============================================

